def transform_final(grid):
    """
    Rule:
    - For vertical bar: find colored cells to right, get source rows, copy each source row's colors to all bar rows
    - For horizontal bar: find colored cells below, get source cols, copy each source col's colors to all bar cols
    """
    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                output[r][c] = 5

    # Handle vertical bars
    for c in range(w):
        bar_rows = sorted([r for r in range(h) if grid[r][c] == 5])
        if len(bar_rows) >= 2 and all(bar_rows[i+1] == bar_rows[i] + 1 for i in range(len(bar_rows)-1)):
            colored_cells = [(r, col_c, grid[r][col_c]) for r in bar_rows for col_c in range(c+1, w)
                             if grid[r][col_c] != 0 and grid[r][col_c] != 5]

            if colored_cells:
                source_rows = sorted(set(r for r, _, _ in colored_cells))
                for sr in source_rows:
                    colors = {ccc: v for r, ccc, v in colored_cells if r == sr}
                    for tr in bar_rows:
                        for ccc, val in colors.items():
                            output[tr][ccc] = val

    # Handle horizontal bars
    for r in range(h):
        bar_cols = sorted([c for c in range(w) if grid[r][c] == 5])
        if len(bar_cols) >= 2 and all(bar_cols[i+1] == bar_cols[i] + 1 for i in range(len(bar_cols)-1)):
            colored_cells = [(c, row_r, grid[row_r][c]) for c in bar_cols for row_r in range(r+1, h)
                             if grid[row_r][c] != 0 and grid[row_r][c] != 5]

            if colored_cells:
                source_cols = sorted(set(c for c, _, _ in colored_cells))
                for sc in source_cols:
                    colors = {rr: v for c, rr, v in colored_cells if c == sc}
                    for tc in bar_cols:
                        for rr, val in colors.items():
                            output[rr][tc] = val

    return output

